Let $f\colon\mathcal{H} \to \left[-\infty,+\infty\right]$ and $\x\in \mathcal{H}$ with $|f(\x)| <+\infty$. The \emph{Fr\'echet subdifferential} of $f$ at $\x$ is given by
\begin{equation*}
\widehat{\partial} f(\x) :=\left\{\bu\in \mathcal{H}:\; \liminf_{\z\to \x}\frac{f(\z)-f(\x)-\langle \bu,\z-\x\rangle}{\|\z-\x\|}\geq 0\right\},
\end{equation*}
the \emph{limiting subdifferential} of $f$ at $\x$ is given by
\begin{equation*}
\partial_L f(\x) :=\left\{\bu\in \mathcal{H}:\; \exists \x_n\st{f}{\to}\x,\ \bu_n\to \bu\text{~~with~~} \bu_n\in \widehat{\partial} f(\x_n)\right\},
\end{equation*}

and the \emph{horizon subdifferential} of $f$ at $\x$ is given by
\begin{equation*}
\partial^{\infty}f(\x) :=\left\{\bu\in \mathcal{H}:\; \exists \x_n\st{f}{\to}\x,\ \lambda_n\downarrow 0,\ \lambda_n\bu_n\to \bu\text{~~with~~} \bu_n\in \widehat{\partial} f(\x_n)\right\}.
\end{equation*}

Here, the notation $\z\st{f}{\to}\x$ means $\z\to \x$ with $f(\z)\to f(\x)$. It follows from the above definition that the limiting subdifferential has the following \emph{robustness property}
\begin{equation*}
\partial_L f(\x) =\left\{\bu\in \mathcal{H}:\; \exists \x_n \st{f}{\to}\x,\ \bu_n\to \bu \text{~~with~~} \bu_n\in \partial_L f(\x_n)\right\}.
\end{equation*}

The \emph{domain} of $\partial_L f$ is $\dom\partial_L f :=\{\x\in \mathcal{H}: \partial_L f(\x)\neq \varnothing\}$. If $f$ is Lipschitz continuous around $\x$, then $\partial_L f(\x)$ is bounded and $\partial^{\infty} f(\x) =\{0\}$ (see \cite[Corollary~1.81]{Mor06}). If $f$ is strictly differentiable\footnote{A function $f$ is strictly differentiable at $\x$ if there exists $\bu \in \mathcal{H}$ such that $\lim_{\y,\z \to \x}\frac{f(\y)-f(\z)-\langle \bu,\y-\z\rangle}{\|\y-\z\|} =0$. Clearly, if $f$ is continuously differentiable at $\x$, then it is strictly differentiable at $\x$.} at $\x$, then $\widehat{\partial} f$ and $\partial_L f$ reduce to the derivative of $f$, denoted by $\nabla f$ (see \cite[Corollary~1.82]{Mor06}). If $f$ is convex, then both Fr\'echet and limiting subdifferentials at $\x$ reduce to the classical subdifferential in convex analysis (see \cite[Theorem~1.93]{Mor06})
\begin{equation*}
\partial f(\x) :=\left\{\bu\in \mathcal{H}:\; \forall \z\in \mathcal{H},\; \langle \bu,\z-\x\rangle\leq f(\z)-f(\x)\right\}.
\end{equation*}

\begin{lemma}[calculus rules]
\label{l:calrules}
Let $f,g\colon \mathcal{H}\to \left(-\infty,+\infty\right]$ be proper lower semicontinuous functions and let $\x \in \dom f$. Then the following statements hold:
\begin{enumerate}
\item\label{l:calrules_separable}
(Separable sum rule) If $f(\x) =\sum_{i=1}^m f_i (x_i)$ with $\x =(x_1,\dots,x_m)$, then $\partial_L f(\x) =\partial_L f_1(x_1) \times \dots \times \partial_L f_m(x_m)$ and $f$ is regular at $\x$ when each $f_i$ regular at $x_i$.

\item\label{l:calrules_sum}
(Sum rule)
If $\partial^{\infty} f(\x) \cap (-\partial^{\infty} g(\x)) =\{0\}$, then $\partial_L(f+g)(\x) \subseteq \partial_L f(\x) + \partial_L g(\x)$, where the equality holds when both $f$ and $g$ are regular at $\x$, in which case $f+g$ is also regular at $\x$. Moreover, if $g$ is strictly differentiable at $\x$, then $\partial_L (f+g)(\x) =\partial_L f(\x) +\nabla g(\x)$.

\item\label{l:calrules_sign}
(Sign rule)
If $f$ is Lipschitz continuous around $\x$ and $\widehat{\partial} f$ is nonempty-valued around $\x$, then $\partial_L (-f)(\x)\subseteq -\partial_L f(\x)$. 

\item\label{l:calrules_quotient}
(Quotient rule) 
Suppose that $f$ and $g$ are Lipschitz continuous around $\x$, and $g(\x)\neq 0$. If $\widehat{\partial} f$ is nonempty-valued around $\x$, then
\begin{equation*}
\partial_L\left(\frac{-f}{g}\right)(\x) \subseteq \frac{-g(\x)\partial_L f(\x) +\partial_L(f(\x)g)(\x)}{g(\x)^2}.
\end{equation*}
If $f$ is strictly differentiable at $\x$, then
\begin{equation*}
\partial_L\left(\frac{-f}{g}\right)(\x) =\frac{-g(\x)\nabla f(\x) +\partial_L(f(\x)g)(\x)}{g(\x)^2}
\end{equation*}
and, consequently, $-f/g$ is regular at $\x$ if and only if $f(\x)g$ is regular at $\x$.

\item\label{l:calrules_sqrt}
(Chain rule and square root rule)
If $f$ is Lipschitz continuous around $\x$ and $\theta\colon \mathbb{R}\to \mathbb{R}$ is continuously differentiable around $f(\x)$,  
then $\partial_L(\theta \circ f)(\x) =\partial_L (\theta'(f(\x))f)(\x)$. In particular, if $f$ is Lipschitz continuous around $\x$ and $f(\x)>0$, then
\begin{equation*}
\partial_L\left(\sqrt{f}\right)(\x) =\frac{\partial_L f(\x)}{2 \sqrt{f(\x)}} \text{~~and~~} \partial_L\left(-\sqrt{f}\right)(\x) =\frac{\partial_L (-f)(\x)}{2 \sqrt{f(\x)}}.
\end{equation*}
\end{enumerate}
\end{lemma}

\begin{lemma}[calculus rules]
\label{l:calrules}
Let $f,g\colon \mathcal{H}\to \left(-\infty,+\infty\right]$ be proper lower semicontinuous functions and let $\x \in \dom f$. Then the following statements hold:
\begin{enumerate}

\item\label{l:calrules_sum}
