If $f$ is Lipschitz continuous around $\x$ and $\widehat{\partial} f$ is nonempty-valued around $\x$, then $\partial_L (-f)(\x)\subseteq -\partial_L f(\x)$.

\item\label{l:calrules_quotient}
(Quotient rule) 
Suppose that $f$ and $g$ are Lipschitz continuous around $\x$, and $g(\x)\neq 0$. If $\widehat{\partial} f$ is nonempty-valued around $\x$, then
\begin{equation*}
\partial_L\left(\frac{-f}{g}\right)(\x) \subseteq \frac{-g(\x)\partial_L f(\x) +\partial_L(f(\x)g)(\x)}{g(\x)^2}.
\end{equation*}
If $f$ is strictly differentiable at $\x$, then
\begin{equation*}
\partial_L\left(\frac{-f}{g}\right)(\x) =\frac{-g(\x)\nabla f(\x) +\partial_L(f(\x)g)(\x)}{g(\x)^2}
\end{equation*}
and, consequently, $-f/g$ is regular at $\x$ if and only if $f(\x)g$ is regular at $\x$.

\item\label{l:calrules_sqrt}
(Chain rule and square root rule)
If $f$ is Lipschitz continuous around $\x$ and $\theta\colon \mathbb{R}\to \mathbb{R}$ is continuously differentiable around $f(\x)$,  
then $\partial_L(\theta \circ f)(\x) =\partial_L (\theta'(f(\x))f)(\x)$. In particular, if $f$ is Lipschitz continuous around $\x$ and $f(\x)>0$, then
\begin{equation*}
\partial_L\left(\sqrt{f}\right)(\x) =\frac{\partial_L f(\x)}{2 \sqrt{f(\x)}} \text{~~and~~} \partial_L\left(-\sqrt{f}\right)(\x) =\frac{\partial_L (-f)(\x)}{2 \sqrt{f(\x)}}.
\end{equation*}

\begin{lemma}
\label{l:subdiff}
Let $\Lambda :=\{\x\in \mathbb{R}^d: \|\x\|=1\}$ and $C_r :=\{\x\in \mathbb{R}^d: \|\x\|_0 \leq r\}$. Given $\x =(x_1,\dots,x_d)\in \mathbb{R}^d$, set $\supp(\x): =\{j: x_j \neq 0\}$. Then the following statements hold:
\begin{enumerate}
\item\label{l:subdiff_l0}
$\forall \x\in \mathbb{R}^d$, $\widehat{\partial} (\|\cdot\|_0)(\x) =\partial_L (\|\cdot\|_0)(\x) =\partial_L^{\infty} (\|\cdot\|_0)(\x) =\{\bv: v_j=0 \text{~if~} j \in \supp(\x)\}$.

\item\label{l:subdiff_sphere}
$\forall \x\in \Lambda$, $\widehat{\partial} \delta_{\Lambda}(\x) =\partial_L \delta_{\Lambda}(\x) =\partial_L^{\infty} \delta_{\Lambda}(\x) =\{ t\x: t \in \mathbb{R}\}$.

\item\label{l:subdiff_ball}
If $\|\x\|_0=r$, then $\partial_L^{\infty} \delta_{C_r}(\x) =\partial_L \delta_{C_r}(\x) =\{\bv: v_j=0 \text{~if~} j \in \supp(\x)\}$. If $\|\x\|_0<r$, then
\begin{multline*}
\partial_L^{\infty} \delta_{C_r}(\x) =\partial_L \delta_{C_r}(\x) =\{\bv: \exists \widehat{J} \subseteq \{1,\dots,d\} \smallsetminus \supp(\x) \text{~with~} |\widehat{J}|=r-\|\x\|_0,\\ v_j=0 \text{~if~} j \in (\supp(\x) \cup \widehat{J})\}.    
\end{multline*}

\item\label{l:subdiff_sum}
$\forall \x\in \Lambda$, $\partial_L (\|\cdot\|_0+\delta_{\Lambda})(\x) =\partial_L (\|\cdot\|_0)(\x) +\partial_L \delta_{\Lambda}(\x)$.

\item\label{l:subdiff_sum'}
$\forall \x\in \Lambda \cap C_r$, $\partial_L (\delta_{C_r}+\delta_{\Lambda})(\x)\subseteq \partial_L\delta_{C_r}(\x) +\partial_L \delta_{\Lambda}(\x)$.
\end{enumerate}
\end{lemma}

\begin{lemma}
\label{l:subdiff}
Let $\Lambda :=\{\x\in \mathbb{R}^d: \|\x\|=1\}$ and $C_r :=\{\x\in \mathbb{R}^d: \|\x\|_0 \leq r\}$. Given $\x =(x_1,\dots,x_d)\in \mathbb{R}^d$, set $\supp(\x): =\{j: x_j \neq 0\}$. Then the following statements hold:
\begin{enumerate}

\item\label{l:subdiff_ball}
If $\|\x\|_0=r$, then $\partial_L^{\infty} \delta_{C_r}(\x) =\partial_L \delta_{C_r}(\x) =\{\bv: v_j=0 \text{~if~} j \in \supp(\x)\}$. If $\|\x\|_0<r$, then
\begin{multline*}
\partial_L^{\infty} \delta_{C_r}(\x) =\partial_L \delta_{C_r}(\x) =\{\bv: \exists \widehat{J} \subseteq \{1,\dots,d\} \smallsetminus \supp(\x) \text{~with~} |\widehat{J}|=r-\|\x\|_0,\\ v_j=0 \text{~if~} j \in (\supp(\x) \cup \widehat{J})\}.    
\end{multline*}

We now consider the global convergence of the full sequence generated by Algorithm~\ref{algo:epasa}. 
Recall that a proper lower semicontinuous function $f\colon \mathcal{H}\to \left(-\infty, +\infty\right]$ is said to satisfy the \emph{KL property} \cite{Kur98,Loj63} at $\overline{\x}\in \dom\partial_L f$ if there exist a neighborhood $U$ of $\overline{\x}$, $\eta \in \left(0,+\infty\right]$, and a continuous concave function $\varphi\colon \left[0, \eta\right)\to \mathbb{R}_+$ such that $\varphi(0) =0$, $\varphi$ is continuously differentiable with $\varphi' >0$ on $\left(0, \eta\right)$, and, for all $\x\in U$ with $f(\overline{\x}) <f(\x) <f(\overline{\x})+\eta$, 
\begin{equation*}
\varphi'(f(\x)-f(\overline{\x}))\dist(0,\partial_L f(\x))\geq 1.
\end{equation*}

\begin{lemma}[cf. {\cite[Theorem 3.6]{LP18}}]
\label{l:LP}
Let $f$ be a proper lower semicontinuous function. Suppose that $f$ satisfies the KL property at $\overline{\x} \in \dom\partial_L f$ with exponent $\alpha \in [\frac{1}{2},1)$. Then, for all $\rho \geq 0$, $\widetilde{f}(\x,\bu)=f(\x)+\rho \|\x-\bu\|^2$ satisfies  the KL property with exponent $\alpha$ at $(\overline{\x},\overline{\x})$.
\end{lemma}

Consider the generalized eigenvalue problem with cardinality regularization
\begin{equation}
\max_{\x \in \mathbb{R}^d} \frac{\x^\top A_1\x}{\x^\top B_1\x}- \lambda \|\x\|_0 
\quad\text{s.t.}\quad \|\x\|=1,
\tag{GEP}
\end{equation}
where $A_1,B_1$ are symmetric matrices such that $A_1$ is positive semidefinite and $B_1$ is positive definite, and $\lambda>0.$ For this generalized eigenvalue problem with cardinality regularization the corresponding merit function for the proposed Algorithm~\ref{algo:epasa} takes the form

\begin{equation*}
\widehat{\Phi}_{GEP}(\x,\bu) =\frac{\x^\top A \x}{\x^\top B \x} +\lambda \|\x\|_0 +\delta_{\Lambda}(\x) +\rho \|\x-\bu\|^2,
\end{equation*}
with $A=-A_1$ a symmetric matrix,  $B=B_1$ is a positive definite matrix, $\Lambda =\{\x\in \mathbb{R}^d: \|\x\|=1\}$, and $\rho \geq 0$. Below, we derive the KL exponent of the merit function $\widehat{\Phi}_{GEP}$. To this end, we will use the following lemma from \cite{LP18}. Here we provide an alternative short proof for it.

\begin{theorem}
\label{t:KL_0norm_reg}
Consider the function
$\Phi(\x)=\frac{\x^\top A\x}{\x^\top B\x}+ \lambda \|\x\|_0 + \delta_{\Lambda}(\x)$,
where $\Lambda=\{\x: \|\x\|=1\}$, $A,B$ are symmetric matrices with $B$ positive definite, and $\lambda>0$. Then $\Phi$ is a KL function with exponent $\frac{1}{2}$. In particular, for all $\rho \geq 0$,
\begin{equation*}
\widehat{\Phi}_{GEP}(\x,\bu)= \frac{\x^\top A\x}{\x^\top B\x}+ \lambda \|\x\|_0 + \delta_{\Lambda}(\x)+ \rho \|\x-\bu\|^2
\end{equation*}
satisfies the KL property with exponent $\frac{1}{2}$ at $(\overline{\x},\overline{\x})$ for all $\overline{\x} \in \dom\partial_L \Phi$ .
\end{theorem}

\begin{lemma}
\label{l:bound}
Let $Q$ be a symmetric $d \times d$ matrix. Then there exists $c>0$ such that, for all $\x \in \mathbb{R}^d$, $\|Q\x\|^2 \geq c\, (\x^\top Q\x)$.
\end{lemma}

\begin{proof}
Let $Q=U^\top \Sigma U$ where $U$ is an orthonormal matrix and $\Sigma={\rm diag}(\lambda_1,\dots,\lambda_n)$ is a diagonal matrix whose diagonal elements are the eigenvalues of $Q$ with $\lambda_1 \leq \lambda_2 \leq \dots \leq \lambda_n$. Let $\x \in \mathbb{R}^d$, $\y:=U\x$, and 
$I_0=\{j:\lambda_j \neq 0\}$. Then $\x^\top Q\x= \sum_{j=1}^N \lambda_j y_j^2 =\sum_{j \in I_0} \lambda_j y_j^2$ and  
\begin{equation*}
\|Q\x\|^2=\x^\top (Q^\top Q)\x= (U\x)^\top \Sigma^2 (U\x)= \sum_{j=1}^N \lambda_j^2 y_j^2=\sum_{j \in I_0} \lambda_j^2 y_j^2.
\end{equation*}
Setting $c :=\min\{|\lambda_j|: j \in I_0\}$, we see that
\begin{equation*}
c\, (\x^\top Q\x)= \sum_{j \in I_0} c\lambda_j y_j^2 \leq \sum_{j \in I_0} c|\lambda_j| y_j^2 \leq \sum_{j \in I_0} |\lambda_j|^2 y_j^2=\|Q\x\|^2,
\end{equation*}
which completes the proof.
\end{proof}

