\begin{proof}
Take any $\overline{\x} \in \dom\partial_L \Phi$. Then $\overline{\x}  \in \Lambda$.
Let $J=\supp(\overline{\x})$ and use $|J|$ to denote the cardinality of $J$.  Choose $\eta \in (0,1)$ such that, for all $\|\x-\overline{\x}\| < \eta$,
\begin{equation*}
\left|\, \frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}-\frac{\x^\top A\x}{\x^\top B\x}\, \right| \leq \frac{\lambda}{4} \text{ and } \eta< \frac{\lambda}{4}.
\end{equation*} Let $\x$ with $\|\x-\overline{\x}\|<\eta$ and  $\Phi(\overline{\x})<\Phi(\x)<\Phi(\overline{\x})+\eta$.
We first see that, by shrinking $\eta$ if necessary, one can assume that
\begin{equation*}
J=\supp(\overline{\x})=\supp(\x).
\end{equation*}
Indeed, by continuity and by shrinking $\eta$ if necessary, one has $\supp(\overline{\x})\subseteq \supp(\x)$. Suppose that $\supp(\overline{\x}) \subsetneq \supp(\x)$. Then $\|\x\|_0>\|\overline{\x}\|_0$, and so,
$\|\x\|_0 \geq \|\overline{\x}\|_0+1$.
From our choice of $\x$, one has $\x \in \Lambda$ and
\begin{equation*}
\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}+ \lambda \|\overline{\x}\|_0< \frac{\x^\top A\x}{\x^\top B\x}+ \lambda \|\x\|_0 <\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}+ \lambda \|\overline{\x}\|_0 +\eta. \end{equation*}
This shows that
$\|\x\|_0<\frac{1}{2}+ \|\overline{\x}\|_0$,
which is impossible.

Using Lemma~\ref{l:subdiff} and noting that $J =\supp(\x)$, we derive that
\begin{multline*}
\partial_L \Phi(\x) \subseteq \Bigg\{\frac{2A\x(\x^\top B\x)-2B\x(\x^\top A\x)}{(\x^\top B\x)^2} +\lambda \bv +t \x:  t \in \mathbb{R}, \\
v_j=0 \text{~if~} j \in J, \text{~and~} v_j \in \mathbb{R} \text{~if~} j \notin J\Bigg\}.
\end{multline*}
Denoting $[a]_J=(a_j)_{j \in J} \in \mathbb{R}^{|J|}$, this implies that
\begin{equation*}
\dist(0, \partial_L \Phi(\x)) \geq \inf_{t \in \mathbb{R}} \left\|\left[\frac{2A\x(\x^\top B\x)-2B\x(\x^\top A\x)}{(\x^\top B\x)^2}\right]_J +t \x_J\right\|.
\end{equation*}
A direct verification shows that
\begin{equation*}
\x^\top  \left( \frac{2A\x(\x^\top B\x)-2B\x(\x^\top A\x)}{(\x^\top B\x)^2}\right) =0,
\end{equation*}
which, together with $J=\supp(\x)$, implies that
\begin{equation*}
(\x_J)^\top \left( \left[\frac{2A\x(\x^\top B\x)-2B\x(\x^\top A\x)}{(\x^\top B\x)^2}\right]_J\right) =0.
\end{equation*}
Therefore,
\begin{equation*}
\dist(0, \partial_L \Phi(\x)) \geq \left\|\left[\frac{2A\x(\x^\top B\x)-2B\x(\x^\top A\x)}{(\x^\top B\x)^2}\right]_J\right\|
=\frac{2}{\x^\top B\x} \left\| [A\x]_J -\frac{\x^\top A\x}{\x^\top B\x} [B\x]_J\right\|.
\end{equation*}
Using $J=\supp(\x)$ again, we have that
\begin{equation*}
[A\x]_J =A_{JJ}\x_J,\; \x^\top A\x =(\x_J)^\top A_{JJ}\x_J,\; [B\x]_J= B_{JJ}\x_J, \text{~and~} \x^\top B\x=(\x_J)^\top B_{JJ}\x_J,
\end{equation*}
and hence $\dist(0, \partial_L \Phi(\x))
\geq \frac{2}{\x^\top B\x} \left\| A_{JJ}\x_J -\frac{\x^\top A\x}{\x^\top B\x} 
B_{JJ}\x_J\right\|$.

Now, let $q(\z) =\z^\top A_{JJ}\z -\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}\, \z^\top B_{JJ}\z$ for $\z \in \mathbb{R}^{|J|}$.
Then
\begin{align*}
\dist(0, \partial_L \Phi(\x))
& \geq \frac{2}{\x^\top B\x} \left\| A_{JJ}\x_J -  \frac{\x^\top A\x}{\x^\top B\x} 
B_{JJ}\x_J\right\| \\
& \geq \frac{2}{\x^\top B\x} \left(\left\| A_{JJ}\x_J -  \frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}} 
B_{JJ}\x_J\right\| - \left|\frac{\x^\top A\x}{\x^\top B\x}-\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}
\right| \, \|B_{JJ}\x_J\|\right) \\
& = \frac{1}{\x^\top B\x} \|\nabla q (\x_J)\| -\frac{2}{\x^\top B\x}|\Phi(\x)-\Phi(\overline{\x})|\, \|B_{JJ}\x_J\|,
\end{align*}
where the second inequality follows from the triangle inequality and the last equality holds as $\x, \overline{\x} \in \Lambda$ and $J=\supp(\x)=\supp(\overline{\x})$ (and so, $\|\x\|_0=\|\overline{\x}\|_0$).

From Lemma \ref{l:bound}, there exists $c>0$ such that, for all $\z$,
$\|\nabla q(\z)\|^2 \geq c\, q(\z)$.
Indeed, one can set $c :=\min_{1 \leq j \leq |J|} \left \{4|\lambda_j(A_{JJ}-\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}B_{JJ})|: \lambda_j(A_{JJ}-\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}B_{JJ}) \neq 0 \right\} $, where $\lambda_j(Q)$ are the eigenvalues of a matrix $Q$. Noting that
\begin{align*}
\frac{q(\x_J)}{\x^\top B\x} &= \left[(\x_J)^\top A_{JJ}(\x_J)-\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}}(\x_J)^\top B_{JJ}(\x_J)\right] \frac{1}{\x^\top B\x} \notag \\
& = \left[\x^\top A\x - \frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}} \x^\top B\x \right] \frac{1}{\x^\top B\x} \notag \\
& = \frac{\x^\top A\x}{\x^\top B\x}-\frac{\overline{\x}^\top A\overline{\x}}{\overline{\x}^\top B\overline{\x}} =\Phi(\x)-\Phi(\overline{\x})>0,
\end{align*}
one has
\begin{align*}
\dist(0, \partial_L \Phi(\x))
&\geq \frac{\sqrt{c} q(\x_J)^{1/2}}{\x^\top B\x} -2|\Phi(\x)-\Phi(\overline{\x})|\frac{\|B_{JJ}\x_J\|}{\x^\top B\x} \\
& = [\Phi(\x)-\Phi(\overline{\x})]^{1/2} \left(\frac{\sqrt{c}}{\sqrt{\x^\top B\x}} -2[\Phi(\x)-\Phi(\overline{\x})]^{1/2}\frac{\|B_{JJ}\x_J\|}{\x^\top B\x}\right).
\end{align*}
Let 
$c_1 :=\min\{\sqrt{\x^\top B\x}: \x \in \Lambda\}$ and $c_2 :=\max\{\sqrt{\x^\top B\x}: \x \in \Lambda\}$. By shrinking $\eta$ if necessary, we can assume that $\eta \in (0,1)$ and
\begin{equation*}
2[\Phi(\x)-\Phi(\overline{\x})]^{1/2}\frac{\|B_{JJ}\x_J\|}{\x^\top B\x}\leq 2\eta^{1/2}\frac{\|B_{JJ}\x_J\|}{c_1}\leq \frac{\sqrt{c}}{2c_2},
\end{equation*}
where the first inequality follows by the fact $\Phi(\overline{\x})<\Phi(\x)<\Phi(\overline{\x})+\eta$. Then, we see that
\begin{equation*}
\dist(0, \partial_L \Phi(\x))
\geq [\Phi(\x)-\Phi(\overline{\x})]^{1/2} \left(\frac{\sqrt{c}}{c_2} -\frac{\sqrt{c}}{2c_2}\right) =\frac{\sqrt{c}}{2c_2}[\Phi(\x)-\Phi(\overline{\x})]^{1/2}.
\end{equation*}
Thus, $\Phi$ satisfies the KL property with exponent $\frac{1}{2}$. This shows that, according to Lemma~\ref{l:LP},
$\widehat{\Phi}_{GEP}$ satisfies the KL property with exponent $\frac{1}{2}$ at $\overline{\x}$ for all $\overline{\x} \in \dom\partial_L \Phi$.
\end{proof}

